<?php
require_once dirname(__DIR__).'/config/config.php';
if(!is_admin()){header('Location: login.php');exit;}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$book=['title'=>'','author'=>'','description'=>'','category_id'=>'','price'=>'','old_price'=>'','cover'=>'','stock'=>0,'is_featured'=>0];$error='';
if($id){$s=$pdo->prepare("SELECT * FROM books WHERE id=?");$s->execute([$id]);$found=$s->fetch();if($found)$book=$found;else{$id=0;}}
$categories=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['title','author','description','cover'] as $field)$book[$field]=trim($_POST[$field]??'');$book['category_id']=(int)($_POST['category_id']??0);$book['price']=(float)($_POST['price']??0);$book['old_price']=($_POST['old_price']??'')!==''?(float)$_POST['old_price']:null;$book['stock']=max(0,(int)($_POST['stock']??0));$book['is_featured']=isset($_POST['is_featured'])?1:0;
 if($book['title']===''||$book['author']===''||$book['price']<0)$error='Title, author and a valid price are required.';
 else{if($id){$s=$pdo->prepare("UPDATE books SET category_id=?,title=?,author=?,description=?,price=?,old_price=?,cover=?,stock=?,is_featured=? WHERE id=?");$s->execute([$book['category_id']?:null,$book['title'],$book['author'],$book['description'],$book['price'],$book['old_price'],$book['cover'],$book['stock'],$book['is_featured'],$id]);}else{$s=$pdo->prepare("INSERT INTO books(category_id,title,author,description,price,old_price,cover,stock,is_featured) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([$book['category_id']?:null,$book['title'],$book['author'],$book['description'],$book['price'],$book['old_price'],$book['cover'],$book['stock'],$book['is_featured']]);}set_flash('Book saved successfully.');header('Location: dashboard.php');exit;}
}
$pageTitle=($id?'Edit book':'Add book').' — OnlineBookStore';include dirname(__DIR__).'/includes/header.php';
?>
<main class="container section"><div class="page-heading"><span class="eyebrow">INVENTORY MANAGEMENT</span><h1><?= $id?'Edit':'Add a new' ?> <span class="gradient-text">book.</span></h1></div><form method="post" class="panel form-stack admin-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php if($error): ?><div class="flash error"><?= e($error) ?></div><?php endif; ?><div class="form-row"><label>Book title<input name="title" required value="<?= e($book['title']) ?>"></label><label>Author<input name="author" required value="<?= e($book['author']) ?>"></label></div><label>Description<textarea name="description" rows="4"><?= e($book['description']) ?></textarea></label><label>Category<select name="category_id"><option value="0">Choose category</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$book['category_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><div class="form-row"><label>Price (₹)<input type="number" min="0" step="0.01" name="price" required value="<?= e($book['price']) ?>"></label><label>Old price (₹)<input type="number" min="0" step="0.01" name="old_price" value="<?= e($book['old_price']) ?>"></label><label>Stock<input type="number" min="0" name="stock" value="<?= e($book['stock']) ?>"></label></div><label>Cover image URL<input name="cover" value="<?= e($book['cover']) ?>" placeholder="https://... or assets/img/book-placeholder.svg"></label><label class="check-label"><input type="checkbox" name="is_featured" <?= $book['is_featured']?'checked':'' ?>> Show as featured book</label><div class="form-row"><button class="btn btn-primary">Save book</button><a class="btn btn-outline" href="dashboard.php">Cancel</a></div></form></main>
<?php include dirname(__DIR__).'/includes/footer.php'; ?>
